/* cppi::22a5914fe36c6e11a69ad49b58c7232b2e5a43a115f5ae3bbb02caf008b8fdf0 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-22' and end_date = '2025-05-22')
and start_date = '2025-05-22' and end_date = '2025-05-22'

/* cppi::4a33463d22e8f5ba92f227b13b7e6a198d7916298909836ba6a219fa01a27823 */
select business_date as date_, security_id, 'SP500_25' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-24' and business_date <= date '2025-06-24' and weight_ndo>0 and id_cppib_index = 'SP500_25_GR_USD_0_0' and security_id is not null

/* cppi::c53fcaff6b04c4919cf5c1a94644c523931c4450ebac4f9bd7b4a901f7e27b8c */
select business_date as date_, security_id, 'SP500_20' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-24' and business_date <= date '2025-06-24' and weight_ndo>0 and id_cppib_index = 'SP500_20_GR_USD_0_0' and security_id is not null

