/* cppi::fbd46ab34fc57c798ae193eaae6bcc6d78cb6be96f8b93f20db2ec933236f28f */
SELECT fx.business_date,        fx.to_currency,        fx.cppib_security_id,        ROUND(1/fx.MID_VAL, 15) AS FX_SPOT FROM risk_prod.FACT_FX_RATE fx WHERE business_date IN ('2025-06-30', '2025-05-30', '2024-04-30', '2024-03-29', '2024-02-29',     '2024-01-31', '2023-12-29', '2023-11-30', '2023-10-31' ) 
 AND fx.RATE_TYPE IN ('SPOT', 'CROSS')   AND fx.FROM_CURRENCY = 'CAD'   AND fx.TO_CURRENCY IN ('USD', 'EUR', 'GBP', 'AUD', 'BRL', 'CNY', 'INR', 'KRW', 'MXN', 'TWD', 'JPY')

